      "id" text PRIMARY KEY NOT NULL,
      "kind" text DEFAULT 'rows', "heading" text, "intro" text, "items" text NOT NULL, "note" text, "tinted" integer DEFAULT false,
      FOREIGN KEY ("_parent_id") REFERENCES "industry"("id") ON UPDATE no action ON DELETE cascade
    );
CREATE TABLE "industry_faqs" (
      "_order" integer NOT NULL,
      "_parent_id" integer NOT NULL,
      "id" text PRIMARY KEY NOT NULL,
      "question" text NOT NULL, "answer" text NOT NULL,
      FOREIGN KEY ("_parent_id") REFERENCES "industry"("id") ON UPDATE no action ON DELETE cascade
    );
CREATE TABLE "industry_rels" (
      "id" integer PRIMARY KEY NOT NULL,
      "order" integer,
      "parent_id" integer NOT NULL,
      "path" text NOT NULL,
      "case_study_id" integer, "section_id" integer REFERENCES "section"("id") ON DELETE cascade,
      FOREIGN KEY ("parent_id") REFERENCES "industry"("id") ON UPDATE no action ON DELETE cascade,
      FOREIGN KEY ("case_study_id") REFERENCES "case_study"("id") ON UPDATE no action ON DELETE cascade
    );
CREATE TABLE "checklist_rels" ("id" integer PRIMARY KEY NOT NULL, "order" integer, "parent_id" integer NOT NULL, "path" text NOT NULL, "section_id" integer, FOREIGN KEY ("parent_id") REFERENCES "checklist"("id") ON UPDATE no action ON DELETE cascade, FOREIGN KEY ("section_id") REFERENCES "section"("id") ON UPDATE no action ON DELETE cascade);
CREATE TABLE "_checklist_v_rels" ("id" integer PRIMARY KEY NOT NULL, "order" integer, "parent_id" integer NOT NULL, "path" text NOT NULL, "section_id" integer, FOREIGN KEY ("parent_id") REFERENCES "_checklist_v"("id") ON UPDATE no action ON DELETE cascade, FOREIGN KEY ("section_id") REFERENCES "section"("id") ON UPDATE no action ON DELETE cascade);
