INSERT INTO "testimonial" ("id", "heading", "client_label", "quote", "order", "updated_at", "created_at") VALUES (1, 'A collaborative product team', 'Canopy client', 'The value of an integrated team is being able to work through product decisions together, early, and with the full context in view.', 1, '2026-09-30T15:45:39.452Z', '2026-09-30T15:45:39.452Z');
INSERT INTO "testimonial" ("id", "heading", "client_label", "quote", "order", "updated_at", "created_at") VALUES (2, 'A thoughtful engineering partner', 'Canopy client', 'We appreciate the care taken to understand the problem, share options, and keep the project moving as one team.', 2, '2026-09-30T15:45:39.530Z', '2026-09-30T15:45:39.530Z');
INSERT INTO "testimonial" ("id", "heading", "client_label", "quote", "order", "updated_at", "created_at") VALUES (3, 'From idea toward a real product', 'Canopy client', 'Bringing design, electronics, and software into the same conversation helped us make more confident decisions.', 3, '2026-09-30T15:45:39.611Z', '2026-09-30T15:45:39.611Z');
