INSERT INTO "section" ("id", "title", "section_key", "heading", "heading_first_line", "heading_second_line", "subheading", "summary", "eyebrow", "tag_line", "highlight", "type", "image_id", "image_url", "logo", "image_alt", "background_image", "background_video", "preview_alt", "mockup_assistant_name", "mockup_scheduling_message", "mockup_sync_title", "mockup_telemetry_title", "body", "cta_label", "cta_href", "secondary_cta_label", "secondary_cta_href", "controls_tabs_label", "controls_previous_label", "controls_next_label", "updated_at", "created_at", "variant", "columns", "anchor", "tags", "hidden", "logo_media_id", "background_image_media_id", "background_video_media_id") VALUES (19, 'Smart Dual-Channel Li-ion Charger - Features', 'features', 'Platform Features & Capabilities', NULL, NULL, 'The charger automatically detects and negotiates charging requirements for each attached battery independently, operating safely across demanding temperature ranges. It features fail-safe default charging profiles, per-output status lighting, comprehensive hardware fault protection (including safe recovery of fully drained batteries), and a compact layout optimized for passive thermal airflow and minimal electrical noise.', NULL, '', NULL, NULL, 'list', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '', '', NULL, NULL, NULL, '2026-10-10T10:44:06.541Z', '2026-10-09T13:01:00.427Z', '', NULL, '', '', 0, NULL, NULL, NULL);
