INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (205, 'The Scoping Call', NULL, 'Connect with us over a call.', NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, 'A working call, not a sales pitch — we get straight to what you''re building, where it stands today, and which disciplines actually need to be in the room.', NULL, NULL, NULL, '', '', NULL, NULL, '', '2026-10-10T10:44:16.258Z', '2026-10-09T13:01:09.342Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (206, 'Select Your Scope', NULL, 'Pick exactly what you need us for.', NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, 'Take the full stack — hardware, firmware, mechanical & industrial design, UI/UX, apps/cloud — or slot us in around what you already have in-house.', NULL, NULL, NULL, '', '', NULL, NULL, '', '2026-10-10T10:44:16.299Z', '2026-10-09T13:01:09.361Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (207, 'Submit the PRD', NULL, 'Bring us what you have — we scope against it, not a guess.', NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, 'Share your product requirements doc, even a rough one. It''s what the proposal gets priced and milestoned against.', NULL, NULL, NULL, '', '', NULL, NULL, '', '2026-10-10T10:44:16.341Z', '2026-10-09T13:01:09.380Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (208, 'Get a Proposal', NULL, 'Fixed milestones, priced against your actual spec.', NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, 'A scoped proposal comes back — real deliverables and a real number, not an open-ended hourly estimate.', NULL, NULL, NULL, '', '', NULL, NULL, '', '2026-10-10T10:44:16.386Z', '2026-10-09T13:01:09.407Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (209, 'Accept & Send PO', NULL, 'One contract. One signature.', NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, 'Accept the proposal and issue a PO — no separate contracts per discipline, no vendor-by-vendor negotiation.', NULL, NULL, NULL, '', '', NULL, NULL, '', '2026-10-10T10:44:16.430Z', '2026-10-09T13:01:09.425Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (210, 'Kickoff', NULL, 'Ideate. Innovate. Deploy.', NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, 'The same team that scoped it is the team that builds it — work starts against the milestones in the proposal.', NULL, NULL, NULL, '', '', NULL, NULL, '', '2026-10-10T10:44:16.473Z', '2026-10-09T13:01:09.445Z', '');
