INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (215, 'What Are You Building?', NULL, '', NULL, 'textarea', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, 'Tell us briefly about your product, requirements, or engineering challenge.', NULL, NULL, NULL, '', '', NULL, NULL, 'field', '2026-10-11T08:36:53.347Z', '2026-10-09T13:01:09.591Z', '');
