INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (219, 'UI/UX & Embedded HMI', NULL, '', NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, 'check', NULL, '', NULL, NULL, NULL, '', '', NULL, NULL, '', '2026-10-10T10:44:17.213Z', '2026-10-09T13:01:09.722Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (220, 'Mobile Apps & Cloud/IoT Dashboards', NULL, '', NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, 'check', NULL, '', NULL, NULL, NULL, '', '', NULL, NULL, '', '2026-10-10T10:44:17.256Z', '2026-10-09T13:01:09.742Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (221, 'How is this different from hiring an agency?', NULL, '', NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, 'An agency subcontracts what it can''t do in-house — you inherit their vendor handoffs. We run every discipline as one internal team, so there''s no seam to hide a bug in.', NULL, NULL, NULL, '', '', NULL, NULL, '', '2026-10-10T10:44:17.450Z', '2026-10-09T13:01:09.819Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (222, 'What if we already have some capability in-house?', NULL, '', NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, 'We slot in around what you already have and own the disciplines you don''t — the engagement scope is defined at the scoping call, not fixed in advance.', NULL, NULL, NULL, '', '', NULL, NULL, '', '2026-10-10T10:44:17.492Z', '2026-10-09T13:01:09.841Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (223, 'How is pricing structured?', NULL, '', NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, 'Every engagement is scoped and priced against fixed milestones after the scoping call and your PRD — a real number for real deliverables, not an hourly rate card.', NULL, NULL, NULL, '', '', NULL, NULL, '', '2026-10-10T10:44:17.534Z', '2026-10-09T13:01:09.869Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (224, 'Who owns the intellectual property?', NULL, '', NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, 'You do. The schematics, PCB layout, firmware source, mechanical CAD, app code and documentation we produce for you belong to you under the contract.', NULL, NULL, NULL, '', '', NULL, NULL, '', '2026-10-10T10:44:17.575Z', '2026-10-09T13:01:09.889Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (225, 'Will you sign an NDA before we share our idea?', NULL, '', NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, 'Yes. Tell us before the scoping call and we sign an NDA first, so you can describe the full idea without holding anything back.', NULL, NULL, NULL, '', '', NULL, NULL, '', '2026-10-10T10:44:17.617Z', '2026-10-09T13:01:09.908Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (226, 'Do we get the source code and design files?', NULL, '', NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, 'Yes, in editable formats, not just a finished board: schematic and layout files, firmware source, mechanical CAD and app code. Any team can pick the product up later, so you are never locked in to us.', NULL, NULL, NULL, '', '', NULL, NULL, '', '2026-10-10T10:44:17.660Z', '2026-10-09T13:01:09.925Z', '');
