INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (231, 'Hardware & PCB', NULL, 'Get the physical layer right once — before a respin costs you the schedule.', NULL, '', NULL, NULL, NULL, 13, NULL, NULL, '', NULL, 'Multi-layer layouts, SI/PI, and BMS circuitry, designed by the same team that writes the firmware running on them.', NULL, NULL, NULL, 'Learn more', '/capabilities/pcb-design/', NULL, NULL, '', '2026-10-12T06:02:38.496Z', '2026-10-09T13:01:10.404Z', 'Multi-Layer PCB, Analog Design, RF Design, Power Electronics, HF Design, FPGA Design, SoC Design');
