INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (233, 'Mechanical & Industrial Design', NULL, 'DFM-checked before tooling, form and finish decided with production cost already in view.', NULL, '', NULL, NULL, NULL, 14, NULL, NULL, '', NULL, 'Thermal CFD simulation, IP67/IP68 sealing, and CMF specification, validated against real tolerance stack-ups — not handed off between two separate teams.', NULL, NULL, NULL, 'Learn more', '/capabilities/mechanical-industrial-design/', NULL, NULL, '', '2026-10-12T06:02:38.723Z', '2026-10-09T13:01:10.441Z', 'DFM-Optimized CAD, Thermal CFD Simulation, IP67 / IP68 Sealing, Tolerance Stack-Up Analysis, Form Factor Optimization, CMF Specification, Human-Centered HMI');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (234, 'UI/UX & HMI', NULL, 'Every screen designed against the real firmware API, not a guess at one.', NULL, '', NULL, NULL, NULL, 15, NULL, NULL, '', NULL, 'Figma prototyping, embedded touchscreen HMI, and brand systems built alongside the hardware, not after it.', NULL, NULL, NULL, 'Learn more', '/capabilities/hmi-ui-ux/', NULL, NULL, '', '2026-10-12T06:02:38.940Z', '2026-10-09T13:01:10.459Z', 'Figma Prototyping, Embedded Touchscreen HMI, Corporate Brand Systems, Design Systems, Usability Testing, Responsive Web UI');
