INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (257, 'Real-Time Operating Systems', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'FreeRTOS and Zephyr architectures with task priorities and memory budgets decided up front, not discovered under load.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-10-13T11:18:27.666Z', '2026-10-13T11:18:27.666Z', 'FreeRTOS, Zephyr, Task Priority & Scheduling, Memory Budgeting');
