INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (260, 'Secure OTA Updates', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Signed images verified before they''re written to the inactive A/B partition, with automatic rollback on a failed or interrupted update.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-10-13T11:18:27.695Z', '2026-10-13T11:18:27.695Z', 'Signed Images, Custom Dual-Bank Bootloader, A/B Partitions, Automatic Rollback');
