INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (365, 'EV Electronics Product Development in India — Battery to Cloud.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'breadcrumb', '2026-10-13T11:18:29.820Z', '2026-10-13T11:18:29.820Z', NULL);
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (366, 'Battery safety is a system problem', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Cell monitoring, protection circuitry and firmware limits have to agree. When the board and the firmware come from different vendors, the gaps show up late, in validation.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-10-13T11:18:29.837Z', '2026-10-13T11:18:29.837Z', NULL);
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (367, 'Field updates decide service cost', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A vehicle in the field needs firmware that can be updated. An OTA-ready architecture with a dual-bank bootloader turns a defect into a patch, not a recall.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-10-13T11:18:29.854Z', '2026-10-13T11:18:29.854Z', NULL);
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (368, 'Heat and ingress decide durability', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Thermal validation and IP67-class sealing belong in the enclosure design from the start, not after the first test failure.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-10-13T11:18:29.854Z', '2026-10-13T11:18:29.854Z', NULL);
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (369, 'PCB Design & Layout', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BMS and charger boards: multi-cell monitoring, high-current power stages, noise and isolation handled in layout.', NULL, NULL, NULL, 'See the capability →', '/capabilities/pcb-design/', NULL, NULL, NULL, '2026-10-13T11:18:29.886Z', '2026-10-13T11:18:29.886Z', NULL);
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (370, 'Firmware Engineering', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'State-of-charge and health tracking, protection logic, interfaces such as CAN and UART, and a dual-bank bootloader that is ready for signed OTA with automatic rollback.', NULL, NULL, NULL, 'See the capability →', '/capabilities/firmware/', NULL, NULL, NULL, '2026-10-13T11:18:29.886Z', '2026-10-13T11:18:29.886Z', NULL);
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (371, 'Mechanical & Industrial Design', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Pack and charger enclosures with thermal CFD, IP67/IP68 sealing and tolerance stack-up checked before tooling.', NULL, NULL, NULL, 'See the capability →', '/capabilities/mechanical-industrial-design/', NULL, NULL, NULL, '2026-10-13T11:18:29.902Z', '2026-10-13T11:18:29.902Z', NULL);
