INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (379, 'Innovate', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Hardware, firmware and enclosure move in parallel, so integration problems surface early.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-10-13T11:18:30.082Z', '2026-10-13T11:18:30.082Z', NULL);
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (380, 'Deploy', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Validation, production handover and a firmware update path for the field.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-10-13T11:18:30.091Z', '2026-10-13T11:18:30.091Z', NULL);
