INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (383, 'Do you build the whole battery management system, or only the firmware?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Both, plus the PCB, the enclosure and the cloud dashboard. One team and one contract, so there is no handoff between board and firmware vendors.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-10-13T11:18:30.142Z', '2026-10-13T11:18:30.142Z', NULL);
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (384, 'Can the battery firmware be updated after the vehicle is sold?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Our BMS architecture is OTA-ready: a dual-bank bootloader with automatic rollback, so updates can be delivered when your platform supports them.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-10-13T11:18:30.158Z', '2026-10-13T11:18:30.158Z', NULL);
