INSERT INTO "case_study" ("id", "title", "slug", "heading", "subheading", "category", "featured", "body", "tags", "images_landing_image_id", "card_cta_label", "card_cta_link", "page_cta_label", "page_cta_link", "project_stage", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id") VALUES (5, 'Smart Battery Management System', 'smart-bms', 'Smart Battery Management System: From an Idea to a Field-Ready Design', 'A robust 4S Li-ion battery management system engineered with field-upgradable OTA capabilities, real-time telemetry, and continuous 20A power delivery.', 'Embedded Systems & Power Electronics', 1, '{"root":{"type":"root","children":[{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Architectural Highlights & Features","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Designed for demanding deployment environments, the system features scalable pack sizes, live OLED/display telemetry showing real-time voltage, runtime, and battery percentage, alongside USB-C fast charging and dual auxiliary power outputs. Controlled via a single-button wake, reset, and display interface, it incorporates comprehensive hardware safety mechanisms and dedicated built-in programming ports.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The Engineering Gap We Closed","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Circuit & Pack Architecture","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Engineered advanced cell balancing topologies, integrated hardware protection circuitry, and optimized thermal stackups for pack-level layout integrity.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Dual-Bank Bootloader (OTA-Ready)","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Implemented a resilient dual-bank bootloader architecture supporting cryptographically signed over-the-air (OTA) updates complete with automated fail-safe rollback execution.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Hardware-in-the-Loop Validation","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Subjected the hardware and firmware to rigorous automated failure injection testing and boundary condition stress before live cells ever touched the prototype.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', 'BMS, Battery Management, Power Electronics, Firmware, FreeRTOS, CAN Bus, OTA, Hardware Validation, ARM Cortex', NULL, 'View Project', '/work/smart-bms/', 'Talk to an Engineer', '#consultation', 'shipped', 'Smart BMS with OTA-Ready Firmware | Canopy Embedded Labs', 'BMS design with fuel gauge, protection circuitry and OTA-ready firmware from one team.', '', 1, 1, 'auto', '2026-10-10T10:44:05.819Z', '2026-10-09T13:01:00.043Z', 'published', '', '', '', NULL);
INSERT INTO "case_study" ("id", "title", "slug", "heading", "subheading", "category", "featured", "body", "tags", "images_landing_image_id", "card_cta_label", "card_cta_link", "page_cta_label", "page_cta_link", "project_stage", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id") VALUES (6, 'Smart Dual-Channel Li-ion Charger', 'dual-channel-charger', 'Smart Dual-Channel Li-ion Charger: Two Channels, One Team', 'A high-efficiency dual-pack charging platform where power stage electronics and control firmware are co-designed from day one.', 'Power Electronics & Firmware', 0, '{"root":{"type":"root","children":[{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Platform Features & Capabilities","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The charger automatically detects and negotiates charging requirements for each attached battery independently, operating safely across demanding temperature ranges. It features fail-safe default charging profiles, per-output status lighting, comprehensive hardware fault protection (including safe recovery of fully drained batteries), and a compact layout optimized for passive thermal airflow and minimal electrical noise.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The Engineering Gap We Closed","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Power Electronics & Two-Channel Architecture","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Engineered independent dual power stages sharing a unified thermal dissipation path and optimized PCB layout budget to eliminate cross-channel interference.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Charge-Control Firmware","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Developed closed-loop charge profile logic written specifically against the physical hardware characteristics rather than relying on generic reference schematics.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Thermal & Enclosure Design","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Validated thermal dissipation performance using Computational Fluid Dynamics (CFD) simulation alongside DFM-optimized enclosure engineering.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', 'Power Electronics, Battery Charger, Firmware, Thermal Design, CFD, Li-ion, Hardware Engineering, Smart BMS', NULL, 'View Project', '/work/dual-channel-charger/', 'Talk to an Engineer', '#consultation', 'shipped', 'Dual-Channel Smart Charger Design | Canopy Embedded Labs', 'Dual-channel Li-ion charger design with power electronics and control firmware engineered together.', '', 1, 1, 'auto', '2026-10-10T10:44:07.128Z', '2026-10-09T13:01:00.666Z', 'published', '', '', '', NULL);
INSERT INTO "case_study" ("id", "title", "slug", "heading", "subheading", "category", "featured", "body", "tags", "images_landing_image_id", "card_cta_label", "card_cta_link", "page_cta_label", "page_cta_link", "project_stage", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id") VALUES (7, 'BLE Mesh + RS485 Node for Energy Meters', 'ble-mesh-rs485-energy-meter', 'BLE Mesh + RS485 Node for Energy Meters: One Board, Two Protocols', 'Retrofitting legacy industrial energy meters with reliable wireless multi-hop connectivity without altering the meter''s internal communication stack.', 'IoT & Wireless Hardware', 1, '{"root":{"type":"root","children":[{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"System Design & Capabilities","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Built for harsh field deployments, this rugged all-weather board features robust surge and reverse-wiring protection, screw-terminal interfaces, non-volatile configuration memory that preserves settings across power cycles, and real-time remote diagnostic reporting.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The Engineering Gap We Closed","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"BLE Mesh Networking","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Engineered a reliable multi-hop mesh upstream architecture featuring seamless node provisioning and automatic network healing without requiring a gateway hardware replacement.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"RS485 / Modbus Bridge","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Developed transparent protocol bridging that interfaces directly with the legacy meter''s native communication stack with zero modifications required to the meter firmware.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Retrofit-Ready Mechanical Design","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Precision-engineered the PCB and mounting geometry to fit directly into the exact physical enclosure footprint already deployed in the field.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', 'BLE Mesh, RS485, Modbus, IoT, Energy Meter, Retrofit, Wireless, Firmware, Hardware Design', NULL, 'View Project', '/work/ble-mesh-rs485-energy-meter/', 'Talk to an Engineer', '#consultation', 'shipped', 'BLE Mesh + RS485 Energy Meter Node | Canopy Embedded Labs', 'BLE Mesh upstream, RS485/Modbus down to the meter, one board.', '', 1, 1, 'auto', '2026-10-10T10:44:08.359Z', '2026-10-09T13:01:01.160Z', 'published', '', '', '', NULL);
