INSERT INTO "_page_v" ("id", "parent_id", "version_title", "version_heading", "version_subheading", "version_url", "version_body", "version_cta_label", "version_cta_href", "version_company_facts_name", "version_company_facts_location", "version_company_facts_contact_email", "version_seo_seo_title", "version_seo_meta_description", "version_seo_canonical_url", "version_seo_robots_index", "version_seo_robots_follow", "version_seo_schema_type", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "version_eyebrow", "version_page_type", "version_seo_keywords", "version_seo_og_title", "version_seo_og_description", "version_seo_og_image_id", "version_hero_image_id") VALUES (320, 3, 'Portfolio', 'Ideas We''ve Turned Into Working Products.', 'Every product here started as somebody else''s idea and a gap in execution capability — no in-house hardware, firmware, or mechanical team to close it. We closed it. Pick a product from the index below to see the full build story, in place — no page reload.', '/work/', NULL, '', '', NULL, NULL, NULL, 'BMS, Charger & IoT Projects | Canopy Embedded Labs', 'Electronics product development portfolio: a smart BMS, a dual-channel Li-ion charger and a BLE Mesh + RS485 energy meter node.', '', 1, 1, 'auto', '2026-10-10T10:39:52.244Z', '2026-09-30T15:45:36.210Z', 'published', '2026-10-10T10:39:52.335Z', '2026-10-10T10:39:52.335Z', 0, 'Electronics Product Development Portfolio', 'landing left', '', '', '', NULL, NULL);
INSERT INTO "_page_v" ("id", "parent_id", "version_title", "version_heading", "version_subheading", "version_url", "version_body", "version_cta_label", "version_cta_href", "version_company_facts_name", "version_company_facts_location", "version_company_facts_contact_email", "version_seo_seo_title", "version_seo_meta_description", "version_seo_canonical_url", "version_seo_robots_index", "version_seo_robots_follow", "version_seo_schema_type", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "version_eyebrow", "version_page_type", "version_seo_keywords", "version_seo_og_title", "version_seo_og_description", "version_seo_og_image_id", "version_hero_image_id") VALUES (321, 7, 'About', 'About Canopy Embedded Labs', 'A full-stack product realization lab in Chennai, India. Ideate. Innovate. Deploy.', '/about/', NULL, '', '', NULL, NULL, NULL, 'About Canopy Embedded Labs | Chennai, India', 'Canopy Embedded Labs is a full-stack electronics product development team in Chennai, India, with 25+ years of R&D experience.', '', 1, 1, 'auto', '2026-10-10T10:44:15.998Z', '2026-10-09T13:01:03.468Z', 'published', '2026-10-10T10:44:16.092Z', '2026-10-10T10:44:16.092Z', 1, '', 'landing left', '', '', '', NULL, NULL);
INSERT INTO "_page_v" ("id", "parent_id", "version_title", "version_heading", "version_subheading", "version_url", "version_body", "version_cta_label", "version_cta_href", "version_company_facts_name", "version_company_facts_location", "version_company_facts_contact_email", "version_seo_seo_title", "version_seo_meta_description", "version_seo_canonical_url", "version_seo_robots_index", "version_seo_robots_follow", "version_seo_schema_type", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "version_eyebrow", "version_page_type", "version_seo_keywords", "version_seo_og_title", "version_seo_og_description", "version_seo_og_image_id", "version_hero_image_id") VALUES (322, 6, 'Engagement Model', 'See the process. Talk to an engineer to start.', 'Whether you''re starting from an idea or already mid-build, the Productized R&D Subscription puts hardware, firmware, mechanical, and cloud under one roof. Six steps, start to kickoff. Send the form and an engineer follows up — no need to wait for a call slot to open up.', '/engagement-model/', '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"We don''t hand off a spec sheet and disappear. One team stays hands-on from first schematic to field-ready product — no vendor handoffs in between.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', '', '', NULL, NULL, NULL, 'Productized R&D Subscription | Canopy Embedded Labs', 'One contract for hardware, firmware, mechanical and cloud. Six steps from scoping call to kickoff, with fixed-milestone pricing.', '', 1, 1, 'FAQPage', '2026-10-10T10:44:17.994Z', '2026-09-30T15:45:36.732Z', 'published', '2026-10-10T10:44:18.120Z', '2026-10-10T10:44:18.120Z', 1, 'Productized R&D Subscription', 'landing', '', '', '', NULL, NULL);
