INSERT INTO "_case_study_v" ("id", "parent_id", "version_title", "version_slug", "version_heading", "version_subheading", "version_category", "version_featured", "version_body", "version_tags", "version_images_landing_image_id", "version_card_cta_label", "version_card_cta_link", "version_page_cta_label", "version_page_cta_link", "version_project_stage", "version_seo_seo_title", "version_seo_meta_description", "version_seo_canonical_url", "version_seo_robots_index", "version_seo_robots_follow", "version_seo_schema_type", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "tags", "version_seo_keywords", "version_seo_og_title", "version_seo_og_description", "version_seo_og_image_id") VALUES (74, 5, 'Smart Battery Management System', 'smart-bms', 'Smart Battery Management System: From an Idea to a Field-Ready Design', 'A robust 4S Li-ion battery management system engineered with field-upgradable OTA capabilities, real-time telemetry, and continuous 20A power delivery.', 'Embedded Systems & Power Electronics', 1, '{"root":{"type":"root","children":[{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Architectural Highlights & Features","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Designed for demanding deployment environments, the system features scalable pack sizes, live OLED/display telemetry showing real-time voltage, runtime, and battery percentage, alongside USB-C fast charging and dual auxiliary power outputs. Controlled via a single-button wake, reset, and display interface, it incorporates comprehensive hardware safety mechanisms and dedicated built-in programming ports.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The Engineering Gap We Closed","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Circuit & Pack Architecture","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Engineered advanced cell balancing topologies, integrated hardware protection circuitry, and optimized thermal stackups for pack-level layout integrity.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Dual-Bank Bootloader (OTA-Ready)","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Implemented a resilient dual-bank bootloader architecture supporting cryptographically signed over-the-air (OTA) updates complete with automated fail-safe rollback execution.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Hardware-in-the-Loop Validation","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Subjected the hardware and firmware to rigorous automated failure injection testing and boundary condition stress before live cells ever touched the prototype.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', 'BMS, Battery Management, Power Electronics, Firmware, FreeRTOS, CAN Bus, OTA, Hardware Validation, ARM Cortex', NULL, 'View Project', '/work/smart-bms/', 'Talk to an Engineer', '#consultation', 'shipped', 'Smart BMS with OTA-Ready Firmware | Canopy Embedded Labs', 'BMS design with fuel gauge, protection circuitry and OTA-ready firmware from one team.', '', 1, 1, 'auto', '2026-10-10T10:44:05.819Z', '2026-10-09T13:01:00.043Z', 'published', '2026-10-13T11:18:27.622Z', '2026-10-13T11:18:27.622Z', 1, NULL, '', '', '', NULL);
INSERT INTO "_case_study_v" ("id", "parent_id", "version_title", "version_slug", "version_heading", "version_subheading", "version_category", "version_featured", "version_body", "version_tags", "version_images_landing_image_id", "version_card_cta_label", "version_card_cta_link", "version_page_cta_label", "version_page_cta_link", "version_project_stage", "version_seo_seo_title", "version_seo_meta_description", "version_seo_canonical_url", "version_seo_robots_index", "version_seo_robots_follow", "version_seo_schema_type", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "tags", "version_seo_keywords", "version_seo_og_title", "version_seo_og_description", "version_seo_og_image_id") VALUES (75, 6, 'Smart Dual-Channel Li-ion Charger', 'dual-channel-charger', 'Smart Dual-Channel Li-ion Charger: Two Channels, One Team', 'A high-efficiency dual-pack charging platform where power stage electronics and control firmware are co-designed from day one.', 'Power Electronics & Firmware', 0, '{"root":{"type":"root","children":[{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Platform Features & Capabilities","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The charger automatically detects and negotiates charging requirements for each attached battery independently, operating safely across demanding temperature ranges. It features fail-safe default charging profiles, per-output status lighting, comprehensive hardware fault protection (including safe recovery of fully drained batteries), and a compact layout optimized for passive thermal airflow and minimal electrical noise.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The Engineering Gap We Closed","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Power Electronics & Two-Channel Architecture","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Engineered independent dual power stages sharing a unified thermal dissipation path and optimized PCB layout budget to eliminate cross-channel interference.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Charge-Control Firmware","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Developed closed-loop charge profile logic written specifically against the physical hardware characteristics rather than relying on generic reference schematics.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Thermal & Enclosure Design","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Validated thermal dissipation performance using Computational Fluid Dynamics (CFD) simulation alongside DFM-optimized enclosure engineering.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', 'Power Electronics, Battery Charger, Firmware, Thermal Design, CFD, Li-ion, Hardware Engineering, Smart BMS', NULL, 'View Project', '/work/dual-channel-charger/', 'Talk to an Engineer', '#consultation', 'shipped', 'Dual-Channel Smart Charger Design | Canopy Embedded Labs', 'Dual-channel Li-ion charger design with power electronics and control firmware engineered together.', '', 1, 1, 'auto', '2026-10-10T10:44:07.128Z', '2026-10-09T13:01:00.666Z', 'published', '2026-10-13T11:18:27.622Z', '2026-10-13T11:18:27.622Z', 1, NULL, '', '', '', NULL);
INSERT INTO "_case_study_v" ("id", "parent_id", "version_title", "version_slug", "version_heading", "version_subheading", "version_category", "version_featured", "version_body", "version_tags", "version_images_landing_image_id", "version_card_cta_label", "version_card_cta_link", "version_page_cta_label", "version_page_cta_link", "version_project_stage", "version_seo_seo_title", "version_seo_meta_description", "version_seo_canonical_url", "version_seo_robots_index", "version_seo_robots_follow", "version_seo_schema_type", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "tags", "version_seo_keywords", "version_seo_og_title", "version_seo_og_description", "version_seo_og_image_id") VALUES (76, 7, 'BLE Mesh + RS485 Node for Energy Meters', 'ble-mesh-rs485-energy-meter', 'BLE Mesh + RS485 Node for Energy Meters: One Board, Two Protocols', 'Retrofitting legacy industrial energy meters with reliable wireless multi-hop connectivity without altering the meter''s internal communication stack.', 'IoT & Wireless Hardware', 1, '{"root":{"type":"root","children":[{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"System Design & Capabilities","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Built for harsh field deployments, this rugged all-weather board features robust surge and reverse-wiring protection, screw-terminal interfaces, non-volatile configuration memory that preserves settings across power cycles, and real-time remote diagnostic reporting.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The Engineering Gap We Closed","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"BLE Mesh Networking","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Engineered a reliable multi-hop mesh upstream architecture featuring seamless node provisioning and automatic network healing without requiring a gateway hardware replacement.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"RS485 / Modbus Bridge","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Developed transparent protocol bridging that interfaces directly with the legacy meter''s native communication stack with zero modifications required to the meter firmware.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Retrofit-Ready Mechanical Design","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Precision-engineered the PCB and mounting geometry to fit directly into the exact physical enclosure footprint already deployed in the field.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', 'BLE Mesh, RS485, Modbus, IoT, Energy Meter, Retrofit, Wireless, Firmware, Hardware Design', NULL, 'View Project', '/work/ble-mesh-rs485-energy-meter/', 'Talk to an Engineer', '#consultation', 'shipped', 'BLE Mesh + RS485 Energy Meter Node | Canopy Embedded Labs', 'BLE Mesh upstream, RS485/Modbus down to the meter, one board.', '', 1, 1, 'auto', '2026-10-10T10:44:08.359Z', '2026-10-09T13:01:01.160Z', 'published', '2026-10-13T11:18:27.622Z', '2026-10-13T11:18:27.622Z', 1, NULL, '', '', '', NULL);
INSERT INTO "blog" ("id", "title", "slug", "heading", "category", "dek", "byline", "published_date", "updated_date", "body", "content_upgrade_label", "content_upgrade_checklist_link_id", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "tags", "image_id", "featured", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id") VALUES (8, 'The Race Condition That Recalled 21,000 EVs', 'bms-race-condition-recall', 'The Race Condition That Recalled 21,000 EVs', 'BMS / EV - Firmware', 'A major automaker''s shared EV platform recalled roughly 21,000 vehicles for a defect inside the battery control unit — a memory-arbitration race between two ICs. Illustrative industry example, not a Canopy Embedded Labs engagement. Here''s what it should change about how you scope BMS and firmware work.', 'By the Canopy Embedded Labs engineering team', '2026-09-30T00:00:00.000Z', '2026-10-02T00:00:00.000Z', '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"A major automaker''s shared EV platform recalled ","version":1},{"type":"text","detail":0,"format":1,"mode":"normal","style":"","text":"roughly 21,000 vehicles","version":1},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":" for a defect inside the battery control unit.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The Root Cause","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"list","listType":"number","tag":"ol","start":1,"children":[{"type":"listitem","value":1,"children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Two ICs on the board could write to the same memory address at the same time.","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"listitem","value":2,"children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"One overwrites the other mid-write.","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"listitem","value":3,"children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The battery ECU faults.","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"listitem","value":4,"children":[{"type":"text","detail":0,"format":1,"mode":"normal","style":"","text":"The vehicle loses drive power on the road.","version":1}],"direction":null,"format":"","indent":0,"version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"This Isn''t Just a \"Software Bug\"","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"This isn''t a software bug in the vague sense marketing teams use. It''s a ","version":1},{"type":"text","detail":0,"format":1,"mode":"normal","style":"","text":"concurrency and memory-arbitration failure","version":1},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":" — the kind unit tests miss, that passes hardware validation, and only shows up when two independent silicon paths race for the same register under real-world timing.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"OTA and Field Remediation","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The manufacturer could fix this with a software update, flashed at the dealer through the OBD-II port. ","version":1},{"type":"text","detail":0,"format":1,"mode":"normal","style":"","text":"Most hardware startups can''t.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"If your BMS or IoT node doesn''t have provisioned OTA and a ","version":1},{"type":"text","detail":0,"format":16,"mode":"normal","style":"","text":"ual-bank bootloade","version":1},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":" from day one, the same class of bug means a truck roll or a physical recall — not a push notification.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Three Things This Should Change About How You Scope BMS/Firmware Work","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"01 - Shared memory access","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Shared memory access between any two ICs (companion chip, fuel gauge, processor) needs explicit arbitration — mutex, semaphore, or a single owner — documented in the architecture review, not discovered in the field.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"02 - OTA & rollback","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"OTA and rollback capability isn''t a \"phase 2\" feature. It''s what turns a per-vehicle recall into a near-zero-cost remote patch.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"03 - End-to-end ownership","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"When your chip vendor, RTOS integrator, and mechanical/enclosure team are three different vendors, concurrency bugs like this hide in the handoffs — nobody owns the full data path end to end.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Our Approach","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"We build BMS and embedded systems as one team — hardware, firmware, and infrastructure under one roof (see our ","version":1},{"type":"link","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"embedded firmware development","version":1}],"direction":null,"format":"","indent":0,"version":3,"fields":{"linkType":"custom","newTab":false,"url":"/capabilities/firmware/"}},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":" work and the ","version":1},{"type":"link","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Smart BMS project","version":1}],"direction":null,"format":"","indent":0,"version":3,"fields":{"linkType":"custom","newTab":false,"url":"/work/smart-bms/"}},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":") — specifically so races like this get caught in architecture review, not in a regulatory filing.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Scope a BMS or IoT product?","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"If you''re scoping a BMS or IoT product and want a second set of eyes on your memory/concurrency architecture before it ships, book a scoping call.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', NULL, NULL, 'BMS Race Condition Recall: 3 Firmware Lessons | Canopy', 'A memory-arbitration race between two ICs forced a 21,000-vehicle EV recall. Three changes it should make to how you scope BMS firmware.', '', 1, 1, 'auto', '2026-10-10T10:44:08.970Z', '2026-10-09T13:01:01.415Z', 'published', 'BMS / EV, Embedded Systems, BMS, EV Engineering, Firmware Engineering, Hardware Startups, Product Engineering', NULL, 1, '', '', '', NULL);
INSERT INTO "blog" ("id", "title", "slug", "heading", "category", "dek", "byline", "published_date", "updated_date", "body", "content_upgrade_label", "content_upgrade_checklist_link_id", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "tags", "image_id", "featured", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id") VALUES (9, 'Your Bootloader Isn''t a Feature. It''s Your Recall Insurance.', 'bootloader-recall-insurance', 'Your Bootloader Isn''t a Feature. It''s Your Recall Insurance.', 'Firmware - OTA', 'A recall is paid per unit; an OTA patch costs almost nothing.', 'By the Canopy Embedded Labs engineering team', '2026-09-29T00:00:00.000Z', NULL, '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"A recall is paid per unit; an OTA patch costs almost nothing.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', NULL, NULL, 'Your Bootloader Isn''t a Feature. It''s Your Recall Insurance. | Canopy Embedded Labs', 'A recall is paid per unit; an OTA patch costs almost nothing.', '', 1, 1, 'auto', '2026-10-10T10:44:09.483Z', '2026-10-09T13:01:01.628Z', 'published', 'Firmware & OTA, OTA, Bootloader', NULL, 0, '', '', '', NULL);
