INSERT INTO "checklist_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked") VALUES (1, 1, '6aca16f420848b23b44f718b', '01', 'OTA + rollback capability designed in from day one', '', 0);
INSERT INTO "checklist_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked") VALUES (2, 1, '6aca16f420848b23b44f718c', '02', 'Shared memory arbitration documented at architecture review', '', 0);
INSERT INTO "checklist_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked") VALUES (3, 1, '6aca16f420848b23b44f718d', '03', 'EMC / SI pre-compliance testing before layout freeze', '', 0);
INSERT INTO "checklist_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked") VALUES (4, 1, '6aca16f420848b23b44f718e', '04', 'Firmware & hardware interaction', 'Are shared buses, interrupts, memory access, and startup sequencing reviewed across the complete system?', 1);
INSERT INTO "checklist_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked") VALUES (5, 1, '6aca16f420848b23b44f718f', '05', 'EMC & signal integrity', 'Do stack-up, return paths, interface timing, and emissions risks have a plan before certification testing?', 1);
INSERT INTO "checklist_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked") VALUES (6, 1, '6aca16f420848b23b44f7190', '06', 'Protection & fault handling', 'Are overload, over-temperature, reverse polarity, and recovery paths designed and validated?', 1);
INSERT INTO "checklist_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked") VALUES (7, 1, '6aca16f420848b23b44f7191', '07', 'Design for manufacturing', 'Has the layout been reviewed for assembly, sourcing, yield, and production test access?', 1);
INSERT INTO "checklist_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked") VALUES (8, 1, '6aca16f420848b23b44f7192', '08', 'Test & programming access', 'Are test points, fixtures, programming, and end-of-line verification planned for the manufacturing process?', 1);
INSERT INTO "checklist_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked") VALUES (9, 1, '6aca16f420848b23b44f7193', '09', 'Field update & recovery', 'Can every unit in the field receive a secure update and recover from an interrupted or failed deployment?', 1);
INSERT INTO "checklist_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked") VALUES (10, 1, '6aca16f420848b23b44f7194', '10', 'Enclosure & environmental', 'Have ingress, vibration, temperature, and service conditions been validated in the final enclosure?', 1);
INSERT INTO "checklist_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked") VALUES (1, 2, '6aca16f420848b23b44f719b', '01', 'BLE/Wi-Fi provisioning flow tested against real-world RF conditions, not just the bench', '', 0);
INSERT INTO "checklist_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked") VALUES (2, 2, '6aca16f420848b23b44f719c', '02', 'Touchscreen HMI response time budgeted and measured under worst-case CPU load', '', 0);
INSERT INTO "checklist_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked") VALUES (3, 2, '6aca16f420848b23b44f719d', '03', 'Offline-first state handling defined for lost connectivity, not just the happy path', '', 0);
