INSERT INTO "_blog_v" ("id", "parent_id", "version_title", "version_slug", "version_heading", "version_category", "version_dek", "version_byline", "version_published_date", "version_updated_date", "version_body", "version_content_upgrade_label", "version_content_upgrade_checklist_link_id", "version_seo_seo_title", "version_seo_meta_description", "version_seo_canonical_url", "version_seo_robots_index", "version_seo_robots_follow", "version_seo_schema_type", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "tags", "version_image_id", "version_tags", "version_featured", "version_seo_keywords", "version_seo_og_title", "version_seo_og_description", "version_seo_og_image_id") VALUES (197, 17, 'What Hardware-in-the-Loop Testing Actually Looks Like', 'hardware-in-the-loop-testing---copy', 'What Hardware-in-the-Loop Testing Actually Looks Like', 'BMS - Behind the Scenes', 'Before firmware ever touches a real pack, it runs against a HIL rig scripted to inject failures on demand. Here''s why.', 'By the Canopy Embedded Labs engineering team', '2026-09-24T00:00:00.000Z', NULL, '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Before firmware ever touches a real pack, it runs against a HIL rig scripted to inject failures on demand. Here''s why.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', '', NULL, 'What Hardware-in-the-Loop Testing Actually Looks Like | Canopy Embedded Labs', 'Before firmware ever touches a real pack, it runs against a HIL rig scripted to inject failures on demand. Here''s why.', '', 1, 1, 'auto', '2026-10-10T10:44:11.726Z', '2026-10-10T12:26:44.430Z', 'draft', '2026-10-10T12:26:44.503Z', '2026-10-10T12:26:44.503Z', 0, NULL, NULL, 'BMS / EV, HIL Testing, Validation', 0, '', '', '', NULL);
INSERT INTO "_blog_v" ("id", "parent_id", "version_title", "version_slug", "version_heading", "version_category", "version_dek", "version_byline", "version_published_date", "version_updated_date", "version_body", "version_content_upgrade_label", "version_content_upgrade_checklist_link_id", "version_seo_seo_title", "version_seo_meta_description", "version_seo_canonical_url", "version_seo_robots_index", "version_seo_robots_follow", "version_seo_schema_type", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "tags", "version_image_id", "version_tags", "version_featured", "version_seo_keywords", "version_seo_og_title", "version_seo_og_description", "version_seo_og_image_id") VALUES (198, 17, 'What Hardware-in-the-Loop Testing Actually Looks Like - Duplicate', 'hardware-in-the-loop-testing---copy', 'What Hardware-in-the-Loop Testing Actually Looks Like', 'BMS - Behind the Scenes', 'Before firmware ever touches a real pack, it runs against a HIL rig scripted to inject failures on demand. Here''s why.', 'By the Canopy Embedded Labs engineering team', '2026-09-24T00:00:00.000Z', NULL, '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Before firmware ever touches a real pack, it runs against a HIL rig scripted to inject failures on demand. Here''s why.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', '', NULL, 'What Hardware-in-the-Loop Testing Actually Looks Like | Canopy Embedded Labs', 'Before firmware ever touches a real pack, it runs against a HIL rig scripted to inject failures on demand. Here''s why.', '', 1, 1, 'auto', '2026-10-10T12:27:07.085Z', '2026-10-10T12:26:44.430Z', 'draft', '2026-10-10T12:27:07.085Z', '2026-10-10T12:27:07.085Z', 1, NULL, NULL, 'BMS / EV, HIL Testing, Validation', 0, '', '', '', NULL);
INSERT INTO "_blog_v" ("id", "parent_id", "version_title", "version_slug", "version_heading", "version_category", "version_dek", "version_byline", "version_published_date", "version_updated_date", "version_body", "version_content_upgrade_label", "version_content_upgrade_checklist_link_id", "version_seo_seo_title", "version_seo_meta_description", "version_seo_canonical_url", "version_seo_robots_index", "version_seo_robots_follow", "version_seo_schema_type", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "tags", "version_image_id", "version_tags", "version_featured", "version_seo_keywords", "version_seo_og_title", "version_seo_og_description", "version_seo_og_image_id") VALUES (199, 8, 'The Race Condition That Recalled 21,000 EVs', 'bms-race-condition-recall', 'The Race Condition That Recalled 21,000 EVs', 'BMS / EV - Firmware', 'A major automaker''s shared EV platform recalled roughly 21,000 vehicles for a defect inside the battery control unit — a memory-arbitration race between two ICs. Illustrative industry example, not a Canopy Embedded Labs engagement. Here''s what it should change about how you scope BMS and firmware work.', 'By the Canopy Embedded Labs engineering team', '2026-09-30T00:00:00.000Z', '2026-10-02T00:00:00.000Z', '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"A major automaker''s shared EV platform recalled ","version":1},{"type":"text","detail":0,"format":1,"mode":"normal","style":"","text":"roughly 21,000 vehicles","version":1},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":" for a defect inside the battery control unit.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The Root Cause","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"list","listType":"number","tag":"ol","start":1,"children":[{"type":"listitem","value":1,"children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Two ICs on the board could write to the same memory address at the same time.","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"listitem","value":2,"children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"One overwrites the other mid-write.","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"listitem","value":3,"children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The battery ECU faults.","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"listitem","value":4,"children":[{"type":"text","detail":0,"format":1,"mode":"normal","style":"","text":"The vehicle loses drive power on the road.","version":1}],"direction":null,"format":"","indent":0,"version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"This Isn''t Just a \"Software Bug\"","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"This isn''t a software bug in the vague sense marketing teams use. It''s a ","version":1},{"type":"text","detail":0,"format":1,"mode":"normal","style":"","text":"concurrency and memory-arbitration failure","version":1},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":" — the kind unit tests miss, that passes hardware validation, and only shows up when two independent silicon paths race for the same register under real-world timing.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"OTA and Field Remediation","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The manufacturer could fix this with a software update, flashed at the dealer through the OBD-II port. ","version":1},{"type":"text","detail":0,"format":1,"mode":"normal","style":"","text":"Most hardware startups can''t.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"If your BMS or IoT node doesn''t have provisioned OTA and a ","version":1},{"type":"text","detail":0,"format":16,"mode":"normal","style":"","text":"ual-bank bootloade","version":1},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":" from day one, the same class of bug means a truck roll or a physical recall — not a push notification.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Three Things This Should Change About How You Scope BMS/Firmware Work","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"01 - Shared memory access","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Shared memory access between any two ICs (companion chip, fuel gauge, processor) needs explicit arbitration — mutex, semaphore, or a single owner — documented in the architecture review, not discovered in the field.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"02 - OTA & rollback","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"OTA and rollback capability isn''t a \"phase 2\" feature. It''s what turns a per-vehicle recall into a near-zero-cost remote patch.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"03 - End-to-end ownership","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"When your chip vendor, RTOS integrator, and mechanical/enclosure team are three different vendors, concurrency bugs like this hide in the handoffs — nobody owns the full data path end to end.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Our Approach","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"We build BMS and embedded systems as one team — hardware, firmware, and infrastructure under one roof (see our ","version":1},{"type":"link","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"embedded firmware development","version":1}],"direction":null,"format":"","indent":0,"version":3,"fields":{"linkType":"custom","newTab":false,"url":"/capabilities/firmware/"}},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":" work and the ","version":1},{"type":"link","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Smart BMS project","version":1}],"direction":null,"format":"","indent":0,"version":3,"fields":{"linkType":"custom","newTab":false,"url":"/work/smart-bms/"}},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":") — specifically so races like this get caught in architecture review, not in a regulatory filing.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Scope a BMS or IoT product?","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"If you''re scoping a BMS or IoT product and want a second set of eyes on your memory/concurrency architecture before it ships, book a scoping call.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', NULL, NULL, 'BMS Race Condition Recall: 3 Firmware Lessons | Canopy', 'A memory-arbitration race between two ICs forced a 21,000-vehicle EV recall. Three changes it should make to how you scope BMS firmware.', '', 1, 1, 'auto', '2026-10-10T10:44:08.970Z', '2026-10-09T13:01:01.415Z', 'published', '2026-10-13T11:18:27.617Z', '2026-10-13T11:18:27.617Z', 1, NULL, NULL, 'BMS / EV, Embedded Systems, BMS, EV Engineering, Firmware Engineering, Hardware Startups, Product Engineering', 1, '', '', '', NULL);
INSERT INTO "_blog_v" ("id", "parent_id", "version_title", "version_slug", "version_heading", "version_category", "version_dek", "version_byline", "version_published_date", "version_updated_date", "version_body", "version_content_upgrade_label", "version_content_upgrade_checklist_link_id", "version_seo_seo_title", "version_seo_meta_description", "version_seo_canonical_url", "version_seo_robots_index", "version_seo_robots_follow", "version_seo_schema_type", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "tags", "version_image_id", "version_tags", "version_featured", "version_seo_keywords", "version_seo_og_title", "version_seo_og_description", "version_seo_og_image_id") VALUES (200, 13, 'The Most Common IoT Support Ticket Isn''t a Hardware Bug', 'iot-support-ticket-ble-provisioning', 'The Most Common IoT Support Ticket Isn''t a Hardware Bug', 'IoT - Mobile', 'It''s BLE provisioning. What actually reduces provisioning-related returns, from firmware/app alignment to real-world RF testing.', 'By the Canopy Embedded Labs engineering team', '2026-09-25T00:00:00.000Z', NULL, '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"It''s BLE provisioning. What actually reduces provisioning-related returns, from firmware/app alignment to real-world RF testing.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', NULL, NULL, 'The Most Common IoT Support Ticket Isn''t a Hardware Bug | Canopy Embedded Labs', 'It''s BLE provisioning. What actually reduces provisioning-related returns, from firmware/app alignment to real-world RF testing.', '', 1, 1, 'auto', '2026-10-10T10:44:11.278Z', '2026-10-09T13:01:02.358Z', 'published', '2026-10-13T11:18:27.617Z', '2026-10-13T11:18:27.617Z', 1, NULL, NULL, 'IoT & Mobile, BLE, Provisioning', 0, '', '', '', NULL);
INSERT INTO "_checklist_v_version_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked", "_uuid") VALUES (1, 42, 411, '01', 'OTA + rollback capability designed in from day one', '', 0, '6aca150266b1816d505d9c21');
INSERT INTO "_checklist_v_version_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked", "_uuid") VALUES (2, 42, 412, '02', 'Shared memory arbitration documented at architecture review', '', 0, '6aca150266b1816d505d9c22');
INSERT INTO "_checklist_v_version_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked", "_uuid") VALUES (3, 42, 413, '03', 'EMC / SI pre-compliance testing before layout freeze', '', 0, '6aca150266b1816d505d9c23');
INSERT INTO "_checklist_v_version_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked", "_uuid") VALUES (4, 42, 414, '04', 'Firmware & hardware interaction', 'Are shared buses, interrupts, memory access, and startup sequencing reviewed across the complete system?', 1, '6aca150266b1816d505d9c24');
INSERT INTO "_checklist_v_version_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked", "_uuid") VALUES (5, 42, 415, '05', 'EMC & signal integrity', 'Do stack-up, return paths, interface timing, and emissions risks have a plan before certification testing?', 1, '6aca150266b1816d505d9c25');
INSERT INTO "_checklist_v_version_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked", "_uuid") VALUES (6, 42, 416, '06', 'Protection & fault handling', 'Are overload, over-temperature, reverse polarity, and recovery paths designed and validated?', 1, '6aca150266b1816d505d9c26');
INSERT INTO "_checklist_v_version_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked", "_uuid") VALUES (7, 42, 417, '07', 'Design for manufacturing', 'Has the layout been reviewed for assembly, sourcing, yield, and production test access?', 1, '6aca150266b1816d505d9c27');
INSERT INTO "_checklist_v_version_items" ("_order", "_parent_id", "id", "number", "heading", "description", "locked", "_uuid") VALUES (8, 42, 418, '08', 'Test & programming access', 'Are test points, fixtures, programming, and end-of-line verification planned for the manufacturing process?', 1, '6aca150266b1816d505d9c28');
